from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.selenium.sbts_fsm3.pages.modals import AddRatModal, DeleteRatModal
from taf.selenium.sbts_fsm3.pages.configuration import configuration_management


class ParameterEditorPage(configuration_management.ParameterEditorPage):

    def __init__(self, driver, download_checker, screenshot_dir):
        super(ParameterEditorPage, self).__init__(driver, download_checker, screenshot_dir)
        self._view_panel = ParameterEditorPageViewPanel(driver, download_checker)

    def add_rat(self, scf_file_path, technology, bands, timeout=60):
        return self._view_panel.add_rat(scf_file_path, technology, bands, timeout)

    def delete_rat(self, technology, bands, timeout=60):
        return self._view_panel.delete_rat(technology, bands, timeout)


class ParameterEditorPageViewPanel(configuration_management.ParameterEditorPageViewPanel):
    _ADD_RAT_BUTTON = '//add-rat-action-button//button'
    _DELETE_RAT_BUTTON = '//delete-rat-action-button//button'

    def __init__(self, driver, download_checker=None):
        super(ParameterEditorPageViewPanel, self).__init__(driver, download_checker)

    def add_rat(self, scf_file_path, technology, bands, timeout=60):
        self.click_enabled_element((By.XPATH, self._ADD_RAT_BUTTON), timeout)

        add_rat_modal = AddRatModal(self.driver)
        add_rat_modal.wait_for_rat_modal_appear(timeout)
        add_rat_modal.load_scf_file(scf_file_path, timeout)
        add_rat_modal.select_technology(technology)
        add_rat_modal.select_band(technology, bands)
        return add_rat_modal.click_add(timeout)

    def delete_rat(self, technology, bands, timeout=60):
        self.click_enabled_element((By.XPATH, self._DELETE_RAT_BUTTON), timeout)

        delete_rat_modal = DeleteRatModal(self.driver)
        delete_rat_modal.wait_for_rat_modal_appear(timeout)
        delete_rat_modal.select_technology(technology)
        delete_rat_modal.select_band(technology, bands)
        return delete_rat_modal.click_delete(timeout)
